sudo apt install unattended-upgrades
sudo dpkg-reconfigure -plow unattended-upgrades    # 交互式启用（写 20auto-upgrades）

# /etc/apt/apt.conf.d/20auto-upgrades
APT::Periodic::Update-Package-Lists "1";
APT::Periodic::Unattended-Upgrade "1";

# /etc/apt/apt.conf.d/50unattended-upgrades 关键项（默认只装 security 更新）
Unattended-Upgrade::Allowed-Origins { "${distro_id}:${distro_codename}-security"; };
Unattended-Upgrade::Mail "ops@example.com";        # 有 MTA 时可发邮件报告
Unattended-Upgrade::Remove-Unused-Dependencies "true";

systemctl status apt-daily-upgrade.timer           # 执行它的定时器
cat /var/log/unattended-upgrades/unattended-upgrades.log   # 执行日志

#!/usr/bin/env bash
set -euo pipefail
usage() { echo "usage: $0 <host> <backup_dir>"; exit 2; }
[[ $# -eq 2 ]] || usage
host="$1"; dir="$2"
[[ -d "$dir" ]] || { echo "目录不存在: $dir" >&2; exit 1; }
echo "backup $host to $dir"

#!/usr/bin/env bash
set -euo pipefail
LOG=/var/log/backup.log
log() { printf '[%s][%s] %s\n' "$(date '+%F %T')" "$1" "${*:2}" | tee -a "$LOG" >&2; }

usage() { echo "usage: $0 -s <src_dir> [-d <dst_dir>]"; exit 2; }
tmpdir=$(mktemp -d)
cleanup() { rm -rf "$tmpdir"; }
trap cleanup EXIT

src=""; dst="/backup"
while getopts ":s:d:h" opt; do
  case $opt in
    s) src="$OPTARG" ;;
    d) dst="$OPTARG" ;;
    h) usage ;;
    *) usage ;;
  esac
done
shift $((OPTIND - 1))

[[ -n "$src" && -d "$src" ]] || { log ERROR "源目录无效: $src"; exit 1; }
mkdir -p "$dst"
log INFO "开始备份 $src"
tar czf "$tmpdir/backup_$(date +%F_%H%M).tar.gz" -C "$(dirname "$src")" "$(basename "$src")"
mv "$tmpdir/backup_"*.tar.gz "$dst/"
log INFO "备份完成: $dst"
